def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: int, total number of seconds represented by the timedelta
    """
    if value is None:
        return None
    return int(value.total_seconds())

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    return value.isoformat()

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if not hasattr(self, "_keys") or self._keys is None:
        return []
    return list(self._keys.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(key)

def values(self, *keys):
    """Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        return list(self.values())

    # Prepare a list of values in insertion order
    values_list = [v for _, v in self.items()]
    result = []

    for key in keys:
        # If key is an integer, treat it as an index
        if isinstance(key, int):
            if key < 0 or key >= len(values_list):
                raise IndexError(f"Index {key} out of range")
            result.append(values_list[key])
        # Otherwise treat it as a dictionary key
        else:
            if key in self:
                result.append(self[key])
            else:
                raise KeyError(f"Key {key!r} not found in record")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys are specified, return all fields
    if not keys:
        return dict(zip(self._keys, self._values))

    result = {}
    for key in keys:
        # Handle integer index
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            field_name = self._keys[key]
            result[field_name] = self._values[key]
        # Handle string key
        else:
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    namespace = {}
    namespace['__slots__'] = tuple(fields)
    namespace['srid_map'] = srid_map
    namespace['__module__'] = __name__

    def __init__(self, *args, **kwargs):
        if len(args) + len(kwargs) != len(fields):
            raise TypeError(f'Expected {len(fields)} arguments, got {len(args)+len(kwargs)}')
        for f, v in zip(fields, args):
            setattr(self, f, v)
        for f, v in kwargs.items():
            if f not in fields:
                raise TypeError(f'Unexpected keyword argument {f!r}')
            setattr(self, f, v)

    def __repr__(self):
        field_str = ', '.join(f'{f}={getattr(self, f)!r}' for f in fields)
        return f'{name}({field_str})'

    namespace['__init__'] = __init__
    namespace['__repr__'] = __repr__

    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def inner(func):
        @functools.wraps(func)
        def new_func(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=3)
            return func(*args, **kwargs)
        return new_func
    return inner

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Strip whitespace and any pre-release/build metadata
    s = s.strip()
    if not s:
        return ()
    # Remove anything after a hyphen or plus (pre-release or build)
    s = s.split('-')[0].split('+')[0]
    parts = s.split('.')
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # ignore non-numeric parts
            continue
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = OrderedDict()

        def _make_key(args, kwargs, typed):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                key += tuple(type(v) for v in kwargs.values())
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            now = timer()
            if key in cache:
                value, expire = cache.pop(key)
                if now < expire:
                    cache[key] = (value, expire)
                    return value
            result = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (result, expire)
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """

    def decorator(func):
        cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            if typed:
                key = tuple((type(arg), arg) for arg in args)
                if kwargs:
                    key += tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
            else:
                key = args
                if kwargs:
                    key += tuple(sorted(kwargs.items()))

            if key in cache:
                cache.move_to_end(key)
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            if maxsize and len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        # Optional helpers
        wrapper.cache = cache
        wrapper.cache_clear = lambda: cache.clear()
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        usage = {}
        def wrapper(*args, **kwargs):
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
                kwkey = tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
            else:
                key = args
                kwkey = tuple(sorted(kwargs.items()))
            full_key = (key, kwkey)
            if full_key in cache:
                usage[full_key] += 1
                return cache[full_key]
            result = func(*args, **kwargs)
            cache[full_key] = result
            usage[full_key] = 1
            if len(cache) > maxsize:
                # Evict the least frequently used item
                lfu_key = min(usage, key=usage.get)
                del cache[lfu_key]
                del usage[lfu_key]
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dict is empty')
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key not in self._value:
        self._value[key] = default
    return self._value[key]

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

