def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        # Skip if this class is a superclass of any other in the list
        if any(issubclass(other, cls) and other is not cls for other in classes):
            continue
        result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = []
    # Determine which attributes to inspect
    if all:
        names = dir(self)
    else:
        names = self.__class__.__dict__.keys()
    for name in names:
        if name.startswith('_'):
            continue
        try:
            value = getattr(self, name)
        except Exception:
            continue
        if callable(value):
            continue
        desc = ''
        if hasattr(value, '__doc__') and value.__doc__:
            desc = value.__doc__
        result.append((name, desc))
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attributes defined on the class itself
    attrs = [
        name
        for name, value in vars(self.__class__).items()
        if not name.startswith("_") and not callable(value)
    ]

    # If requested, include attributes from base classes
    if all:
        for base in self.__class__.__mro__[1:]:
            attrs.extend(
                [
                    name
                    for name, value in vars(base).items()
                    if not name.startswith("_") and not callable(value)
                ]
            )

    # Return a sorted list of unique attribute names
    return sorted(set(attrs))

