def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in response")
        # Initialize the field if it does not exist yet
        if field not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                last_applied_manifest[field] = {}
            else:
                last_applied_manifest[field] = response[field]
        # If the field is a nested dictionary, recurse
        if isinstance(sub_schema, dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, response[field]
            )
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schema attribute exists
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}
    # Default schema to apply when none is specified
    default_schema = {"status": {"type": "object"}}
    # Iterate over all resources in the manifest
    for resource in getattr(app.spec, "manifest", []):
        kind = resource.get("kind")
        if kind and kind not in app.spec.observer_schema:
            # Use a shallow copy to avoid accidental sharing
            app.spec.observer_schema[kind] = default_schema.copy()

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not os.path.exists(path):
            return False
        if not os.path.isdir(path):
            return False
        # Check for .ocfl_version file
        version_file = os.path.join(path, '.ocfl_version')
        if not os.path.isfile(version_file):
            return False
        # Basic validation of the version file content
        with open(version_file, 'r') as f:
            content = f.read().strip()
        if not content:
            return False
        # Ensure the version string is numeric (e.g., "1.0")
        if not content.replace('.', '').isdigit():
            return False
        # Additional checks for OCFL structure could be added here
        return True
    except Exception:
        return False

