def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    mapping = {}
    for logical_path, entries in inventory.items():
        files = set()
        # If entries is a dict mapping version -> iterable of content files
        if isinstance(entries, dict):
            for v, content_files in entries.items():
                try:
                    # Compare versions if possible
                    if v >= version:
                        files.update(content_files)
                except Exception:
                    # Fallback to string comparison
                    if str(v) >= str(version):
                        files.update(content_files)
        # If entries is an iterable of (version, content_file) tuples
        elif hasattr(entries, "__iter__"):
            for v, content_file in entries:
                try:
                    if v >= version:
                        files.add(content_file)
                except Exception:
                    if str(v) >= str(version):
                        files.add(content_file)
        if files:
            mapping[logical_path] = files
    return mapping

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    seen = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        for key in ('path', 'hash', 'size'):
            if key not in entry:
                raise ValueError(f"File entry missing required key '{key}'")
        path = entry['path']
        if not isinstance(path, str):
            raise ValueError("File 'path' must be a string")
        if path not in manifest_files:
            raise ValueError(f"File '{path}' referenced in fixity but not present in manifest")
        if path in seen:
            raise ValueError(f"Duplicate file entry for '{path}' in fixity")
        seen.add(path)
        if not isinstance(entry['hash'], str):
            raise ValueError(f"Hash for file '{path}' must be a string")
        if not isinstance(entry['size'], int):
            raise ValueError(f"Size for file '{path}' must be an integer")
    return True

def files_list(path):
    """Return the files in `path`"""
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [os.path.join(path, f) for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))]
    raise FileNotFoundError(path)

