def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    default = 'unknown'

    # Attempt to read a simple VERSION file
    try:
        with open('VERSION', 'r') as f:
            return f.read().strip()
    except Exception:
        pass

    # Attempt to read a version from a version.py file
    try:
        with open('version.py', 'r') as f:
            for line in f:
                stripped = line.strip()
                if stripped.startswith('__version__'):
                    _, val = stripped.split('=', 1)
                    return val.strip().strip('\'"')
    except Exception:
        pass

    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == 'plain':
        return ''.join(str(p) for p in pieces)
    elif style == 'html':
        html_parts = []
        for p in pieces:
            if isinstance(p, dict):
                text = p.get('text', '')
                cls = p.get('class', '')
                if cls:
                    html_parts.append('<span class="{0}">{1}</span>'.format(cls, text))
                else:
                    html_parts.append('<p>{0}</p>'.format(text))
            else:
                html_parts.append('<p>{0}</p>'.format(p))
        return ''.join(html_parts)
    elif style == 'markdown':
        md_parts = []
        for p in pieces:
            if isinstance(p, dict):
                md_parts.append(p.get('text', ''))
            else:
                md_parts.append(str(p))
        return '\n\n'.join(md_parts)
    elif style == 'json':
        import json
        return json.dumps(pieces)
    else:
        raise ValueError('Unsupported style: {0}'.format(style))

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
