def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    outputs = []
    for cmd in commands:
        cmd_list = [cmd] + list(args)
        if verbose:
            print("Running command:", ' '.join(cmd_list))
        stderr = subprocess.DEVNULL if hide_stderr else None
        try:
            output = subprocess.check_output(cmd_list, cwd=cwd, env=env, stderr=stderr, shell=False)
            outputs.append(output)
        except subprocess.CalledProcessError as e:
            raise
    return outputs

def register_vcs_handler(vcs, method):  # tyoe: (str, str) -> typing.Callable  # decorator
