def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Retrieve the root of the hierarchy; it may be a list, tuple, or dict
    root = getattr(self, "_root", None)
    if root is None:
        return num_objects, good_objects

    if isinstance(root, dict):
        iterable = root.values()
    else:
        iterable = root

    for obj in iterable:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            validate_method = getattr(obj, "validate", None)
            if callable(validate_method):
                try:
                    validate_method()
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Validation failed for {obj!r}: {exc}")
            else:
                # If no validate method, assume it's valid
                pass

        # Check the digest if requested and the object passed validation
        if check_digests and is_valid:
            try:
                import hashlib
                data = getattr(obj, "data", None)
                if data is None:
                    raise ValueError("Object has no 'data' attribute")
                if isinstance(data, str):
                    data = data.encode("utf-8")
                computed_digest = hashlib.sha256(data).hexdigest()
                stored_digest = getattr(obj, "digest", None)
                if stored_digest != computed_digest:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Digest mismatch for {obj!r}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not hasattr(self, 'root_inventory') or self.root_inventory is None:
        raise ValueError('Root inventory not available for comparison')
    self.different_digests = {}
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, 'inventory.json')
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f'Inventory file missing for version directory {vdir}')
        with open(inv_path, 'r') as f:
            try:
                inv = json.load(f)
            except Exception as e:
                raise ValueError(f'Failed to parse inventory at {inv_path}: {e}')
        if not isinstance(inv, dict):
            raise ValueError(f'Inventory at {inv_path} must be a mapping of file to digest')
        # Record differences between this inventory and the root inventory
        diffs = {fname: digest for fname, digest in inv.items()
                 if self.root_inventory.get(fname) != digest}
        if diffs:
            self.different_digests[vdir] = diffs
    return self

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f'path does not exist: {path}'

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        # Check if this directory itself contains a Namaste file
        for entry in os.listdir(path):
            if entry.startswith('0='):
                return 'object'

        # No Namaste file in this dir; look for subdirectories that contain one
        for entry in os.listdir(path):
            sub = os.path.join(path, entry)
            if os.path.isdir(sub):
                for subentry in os.listdir(sub):
                    if subentry.startswith('0='):
                        return 'root'

        return 'unknown directory type'

    return 'unknown path type'

