def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import OrderedDict

    def merge_mapping_nodes(node1, node2):
        """Recursively merge two MappingNode objects."""
        merged = OrderedDict()
        # Add items from the first node
        for k, v in node1.value:
            merged[k.value] = (k, v)
        # Merge items from the second node
        for k, v in node2.value:
            key = k.value
            if key in merged:
                existing_k, existing_v = merged[key]
                if isinstance(existing_v, MappingNode) and isinstance(v, MappingNode):
                    merged[key] = (existing_k, merge_mapping_nodes(existing_v, v))
                else:
                    # Last value wins for non-mapping types
                    merged[key] = (existing_k, v)
            else:
                merged[key] = (k, v)
        # Build the merged value list
        merged_list = [item for item in merged.values()]
        return MappingNode(tag=node1.tag, value=merged_list)

    result = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in result:
            result[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = result[key]
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                merged_node = merge_mapping_nodes(existing_value_node, value_node)
                result[key] = (existing_key_node, merged_node)
            else:
                # Last value wins for non-mapping types
                result[key] = (existing_key_node, value_node)
    return list(result.values())

