def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        return 0
    size = size.strip()
    if not size:
        return 0

    num_str = ''
    unit_str = ''
    for ch in size:
        if ch.isdigit() or ch == '.':
            num_str += ch
        else:
            unit_str += ch

    if not num_str:
        return 0

    try:
        num = float(num_str)
    except ValueError:
        return 0

    unit = unit_str.strip().lower()
    if unit in ('', 'b'):
        factor = 1
    elif unit in ('k', 'kb'):
        factor = 1000
    elif unit in ('m', 'mb'):
        factor = 1000 ** 2
    elif unit in ('g', 'gb'):
        factor = 1000 ** 3
    elif unit in ('t', 'tb'):
        factor = 1000 ** 4
    elif unit in ('p', 'pb'):
        factor = 1000 ** 5
    elif unit in ('e', 'eb'):
        factor = 1000 ** 6
    elif unit in ('z', 'zb'):
        factor = 1000 ** 7
    elif unit in ('y', 'yb'):
        factor = 1000 ** 8
    else:
        factor = 1

    return int(round(num * factor))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''
    if not url_args:
        return url

    for key, value in url_args.items():
        if value is None:
            continue
        placeholder_braces = '{' + key + '}'
        placeholder_colon = ':' + key
        url = url.replace(placeholder_braces, str(value))
        url = url.replace(placeholder_colon, str(value))
    return url

