def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dict is empty')
    # Find key with minimum frequency
    if hasattr(self, '_freq'):
        min_key = min(self._freq, key=lambda k: self._freq[k])
    else:
        # Assume each value is a tuple (value, freq) or has a 'freq' attribute
        min_key = min(self, key=lambda k: getattr(self[k], 'freq', 0))
    value = self[min_key]
    del self[min_key]
    return (min_key, value)

