    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # If a tree is passed, use its root element
    if hasattr(node, 'getroot'):
        node = node.getroot()
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            # If we already have a value, convert to a list
            if isinstance(result[key], list):
                result[key].append(child)
            else:
                result[key] = [result[key], child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Ensure base URL has no trailing slash
    base = url.rstrip('/')
    # Default NodeInfo document path
    if document_path is None:
        document_path = '/.well-known/nodeinfo/1.0.json'
    # Ensure the path starts with a slash
    if not document_path.startswith('/'):
        document_path = '/' + document_path
    href = f"{base}{document_path}"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        # If it's a dict, return it directly
        if isinstance(data, dict):
            return data
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_el = root.find("xrd:Subject", ns)
        subject = subject_el.text if subject_el is not None else None
        aliases = [a.text for a in root.findall("xrd:Alias", ns) if a.text]
        links = []
        for link_el in root.findall("xrd:Link", ns):
            rel = link_el.attrib.get("rel")
            href = link_el.attrib.get("href")
            type_ = link_el.attrib.get("type")
            links.append({"rel": rel, "href": href, "type": type_})
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        # Normalize handle to include the acct: scheme
        if handle.startswith("acct:"):
            acct_handle = handle
            handle_no_acct = handle[5:]
        else:
            acct_handle = f"acct:{handle}"
            handle_no_acct = handle

        # Extract host from the handle
        if "@" not in handle_no_acct:
            return None
        host = handle_no_acct.split("@", 1)[1]

        # Build the webfinger URL
        url = f"https://{host}/.well-known/webfinger?resource={quote(acct_handle)}"

        # Retrieve the document
        with closing(urllib2.urlopen(url)) as page:
            return page.read()
    except Exception:
        # Any error (network, HTTP, parsing) results in a graceful None
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
