def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def resolve(parser_name, visited):
        if parser_name in visited:
            raise ValueError(f"Circular include detected: {' -> '.join(visited + [parser_name])}")
        visited.append(parser_name)
        parser = parser_dict.get(parser_name)
        if not parser:
            raise KeyError(f"Parser '{parser_name}' not found for include resolution.")
        includes = parser.get('include')
        if not includes:
            return
        if isinstance(includes, str):
            includes = [includes]
        for inc in includes:
            if inc not in parser_dict:
                raise KeyError(f"Included parser '{inc}' not found for parser '{parser_name}'.")
            resolve(inc, visited.copy())
            inc_parser = parser_dict[inc]
            for k, v in inc_parser.items():
                if k == 'include':
                    continue
                if k not in parser:
                    parser[k] = v
                else:
                    if isinstance(parser[k], dict) and isinstance(v, dict):
                        parser[k].update(v)
        parser.pop('include', None)

    for pname in list(parser_dict.keys()):
        resolve(pname, [])

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Resolve value from spec if available, otherwise use the option's default
        if hasattr(self, "spec"):
            try:
                # Try dict-like access first
                val = self.spec.get(arg.name, arg.default)
            except AttributeError:
                # Fallback to attribute access
                val = getattr(self.spec, arg.name, arg.default)
        else:
            val = arg.default

        # If the spec explicitly provides None, fall back to the default
        if val is None:
            val = arg.default

        # Handle nested dictionary options by merging nested defaults
        if isinstance(arg, DictOption) and isinstance(val, dict):
            nested = arg.scheme.get_spec_defaults()
            merged = {**nested, **val}
            defaults[arg.name] = merged
        else:
            defaults[arg.name] = val

    return defaults

