def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not hasattr(self, "_specs"):
        raise AttributeError("No option specifications available")
    command_specs = self._specs.get(command_name)
    if command_specs is None:
        raise KeyError(f"Command '{command_name}' not found in option specifications")
    spec = command_specs.get(argument_name)
    if spec is None:
        raise KeyError(f"Argument '{argument_name}' not found for command '{command_name}'")
    return spec

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', [])
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # get option name
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)
        if not name or not cond:
            continue
        # evaluate condition
        try:
            if callable(cond):
                if cond(args):
                    required.append(name)
            else:
                # treat condition as a string expression
                if eval(cond, {}, {'args': args, 'command_name': command_name}):
                    required.append(name)
        except Exception:
            # ignore errors in condition evaluation
            pass
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Iterate over each provided argument
    for arg_name, value in args.items():
        # Retrieve the argument definition from the parsed YAML
        arg_def = self.parsed_yaml.get('args', {}).get(arg_name, {})
        max_len = arg_def.get('length')
        if max_len is None:
            # No length constraint defined for this argument
            continue
        # Attempt to determine the length of the value
        try:
            val_len = len(value)
        except TypeError:
            # Value does not support len(), skip length check
            continue
        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})

    # Helper to validate a single argument
    def _validate(arg_name, arg_attrs):
        if 'choices' not in arg_attrs:
            return
        if arg_name not in args:
            return
        value = args[arg_name]
        if value not in arg_attrs['choices']:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value}. "
                f"Expected one of {arg_attrs['choices']}"
            )

    # Handle both dict and list forms of argument definitions
    if isinstance(arg_defs, dict):
        for name, attrs in arg_defs.items():
            _validate(name, attrs)
    else:  # list of single-key dicts
        for arg_dict in arg_defs:
            name, attrs = next(iter(arg_dict.items()))
            _validate(name, attrs)

