def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare containers for control and nested arguments
    control_args = {}
    nested_args = {}

    # Helper to process a key/value pair
    def _add_arg(key, value):
        # Normalize key: strip leading dashes if present
        key_name = key.lstrip('-')
        # Determine if this is a control argument
        if key_name.startswith('control_'):
            control_args[key_name] = value
        # Custom arguments are treated as nested but may be flagged
        elif key_name.startswith('custom_'):
            nested_args[key_name] = value
        else:
            nested_args[key_name] = value

    # If args is a dict, iterate over items
    if isinstance(args, dict):
        for k, v in args.items():
            _add_arg(k, v)
    # If args is a list or tuple, assume alternating key/value pairs
    elif isinstance(args, (list, tuple)):
        it = iter(args)
        for key in it:
            try:
                value = next(it)
            except StopIteration:
                value = None
            _add_arg(key, value)
    else:
        # Unsupported type: return empty dicts
        return {}, {}

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                vars_dict[item[0]] = item[1]
            else:
                # ignore invalid items
                pass
    else:
        # If extra_vars is a single dict-like object
        if hasattr(extra_vars, "items"):
            vars_dict.update(extra_vars)
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Find the plugin spec file (JSON or YAML)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break

    if not spec_path:
        return {}

    # Load the spec
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            data = json.load(f)
        else:
            if yaml is None:
                raise RuntimeError("yaml module not available to load plugin spec")
            data = yaml.safe_load(f)

    # Flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    path = os.path.normpath(path)
    root = os.path.normpath(root)
    rel = os.path.relpath(path, root)
    if rel == '.':
        return ''
    if rel.startswith('..'):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return rel
